	$(document).ready(function() {
		$(function(){
			$('#searchWindowBox').click(function(){
				$('#searchWindowBox').removeAttr('placeholder');
			});
			 $('#searchWindowBox').blur(function(){
				$('#searchWindowBox').attr('placeholder','검색하기');
			});
		});

		$(function() {
			// ENTER KEY EVENT
			$("#searchWindowBox").keydown(function(key)  {
				if  ( key.keyCode == 13 )  {
					topSearch();
				}
			});
		});

		// 메인 팝업 확인 (1일 닫기)
		var nowDate = new Date();
		var mainPopupData1 = localStorage.getItem('MAIN_cookiePop_1');
		var mainPopupData2 = localStorage.getItem('MAIN_cookiePop_2');
		var mainPopupData3 = localStorage.getItem('MAIN_cookiePop_3');
		var mainPopupData4 = localStorage.getItem('MAIN_cookiePop_4');
		var mainPopupData5 = localStorage.getItem('MAIN_cookiePop_5');

		if  ( (null == mainPopupData1 || mainPopupData1 == '') || (mainPopupData1 < getFormatDate(nowDate,'')) )  {  $(".MAIN_POPUP_1").show();  }
		if  ( (null == mainPopupData2 || mainPopupData2 == '') || (mainPopupData2 < getFormatDate(nowDate,'')) )  {  $(".MAIN_POPUP_2").show();  }
		if  ( (null == mainPopupData3 || mainPopupData3 == '') || (mainPopupData3 < getFormatDate(nowDate,'')) )  {  $(".MAIN_POPUP_3").show();  }
		if  ( (null == mainPopupData4 || mainPopupData4 == '') || (mainPopupData4 < getFormatDate(nowDate,'')) )  {  $(".MAIN_POPUP_4").show();  }
		if  ( (null == mainPopupData5 || mainPopupData5 == '') || (mainPopupData5 < getFormatDate(nowDate,'')) )  {  $(".MAIN_POPUP_5").show();  }

		$(".checkbox").click(function()  {
			var oneDayCloseData = "";
			oneDayCloseData = "MAIN_cookiePop_" + $(this).val();
 			localStorage.setItem(oneDayCloseData,getFormatDate(nowDate,''));
			$(this).parents("div").hide();
		});

		$(".close").click(function()  {
			$(this).parents("div").hide();
		});

        $(".box_t01").mouseover(function()  {
        	mouseOver($(this));
        }).mouseout(function()  {
        	mouseOut($(this));
        });

        $("#section01 a").focus(function()  {
        	mouseOver($(this).find('.box_t01'));
        }).focusout(function()  {
        	mouseOut($(this));
        });

	});

	function topSearch() {
		location.href="/etc/searchMain.do?query="+$("#searchWindowBox").val()+"";
	}

	function mouseOver(val) {
		var width_size = window.outerWidth;
		if  ( 'PC' == 'PC' && width_size > 780 )  {
			val.find("dd:eq(0)").hide();
			val.find("dd:eq(1)").show();
    	}
	}

	function mouseOut(val) {
		var width_size = window.outerWidth;
		if  ( 'PC' == 'PC' && width_size > 780 )  {
			val.find("dd:eq(1)").hide();
			val.find("dd:eq(0)").show();
    	}
	}

	/* 팝업존 팝업창 형태 호출 */
	function fn_openPopupZoneWindow(link, popupNm, width, height, left, top )  {

		if  ( null == link || '' == link ) return false;

		if  ( null == width || '' == width )  width = 1024;
		if  ( null == height || '' == height )  height = 768;
		if  ( null == left || '' == left )  left = 100;
		if  ( null == top || '' == top )  top = 100;

		window.open(link, popupNm, "width="+width+", height="+height+", left="+left+", top="+top);

	}

	// 상세보기 페이지 이동
	function fn_goView(boardNo, boardMngNo, seq )  {

		$("input[name=boardNo]").val(boardNo);
		$("input[name=boardMngNo]").val(boardMngNo);
		$("input[name=seq]").val(seq);

		$("#viewForm").attr("method", "post");
        $("#viewForm").attr("action", "/board/"+boardMngNo+"/view.do");
        $("#viewForm").submit();

	}

	// 파일다운로드
	function fn_down(fileSe, file){
		location.href = "/FilePathDown.do?fileSe=" + fileSe + "&file=" + file;
	}

$(function(e){
	$('#select_year button').on('click',function(e){
		$('#select_year').toggleClass('open');
	});
	$('#select_year a').on('click',function(e){
		e.preventDefault();
		var value = $(this).parents('li').attr('data-year');
		$('#select_year').removeClass('open');
		$('#privacy_pop .box').removeClass('on');
		$('#privacy_pop .box[data-year='+value+']').addClass('on');
		$('#privacy_pop .btn_area > div').removeClass('on');
		$('#privacy_pop .btn_area > div[data-year='+value+']').addClass('on');
		var txt = $(this).parents('li').text();
		$('#select_year button').text(txt);

		$('#select_year button').focus();
		$('#select_year li a').attr('title',"");
		$(this).parents('li').find('a').attr('title',"선택됨");

		$('#privacy_pop .box').off('scroll, touchmove, mousewheel');
	});
});

	$(document).ready(function() {
        // 메인 개인정보처리방침 레이어 팝업 노출
        if(location.hash == "#privacy") {
        	$.fn.fullpage.moveTo(6);
        	$('.btn_privacy').click();
        }
	});

